KG42.register("edges-48b6a52cfd62287e66c7b666",{"id":"S-4d4353cc5d65432c","source":"COMP-b3f649e90c1f17b9","type":"precedes","target":"COMP-3e8ef790cad9c018","evidence_class":"S","scientific_acceptance":false,"relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"paper_ids":["12-p2p_microgrid_trading"],"assertions":[{"id":"12-p2p_microgrid_trading::v141-c-R009::E::v141-c-R009-E002","paper":"12-p2p_microgrid_trading","rule_id":"v141-c-R009","rule_ref":"12-p2p_microgrid_trading::v141-c-R009","record":{"edge_id":"v141-c-R009-E002","source":"bidding.supply","target":"execution.energy_trade","type":"precedes","constraint_ids":["v141-c-R009-C001"],"evidence_ids":["v141-b-g01-ev-21"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R009-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-b3f649e90c1f17b9","target":"COMP-3e8ef790cad9c018","source_occurrence_id":"12-p2p_microgrid_trading::v141-c-R009::V::bidding.supply","target_occurrence_id":"12-p2p_microgrid_trading::v141-c-R009::V::execution.energy_trade","source_unit_id":"12-p2p_microgrid_trading::v141-a-M02::bidding.supply","target_unit_id":"12-p2p_microgrid_trading::v141-a-M02::execution.energy_trade","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Elecbay energy exchange following the order acceptance/rejection process. | Elecbay peer publishing and bidding for a corresponding half-hourly energy exchange period. | Elecbay supplier trades addressing deviations from promised energy generation or consumption. | Energy consumers and prosumers trading through Elecbay in LV distribution networks.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-17","v141-b-g01-ev-18","v141-b-g01-ev-21","v141-b-g01-ev-28"]},"active":true,"source_signature":"484caf327b69824a9ccc79f67dcda6ada50f598bcc17511bbd35bacc10f46aa7","relation_scope":"original_occurrence_pair_only","internal_to_parent":false,"source_science":{"mechanism_id":"v141-a-M02","source_definition":"Buyers' demand submissions provide the listed half-hour energy requirements that sellers browse when placing supply orders. Scope: Elecbay alternative seller-initiated order placement for half-hour energy requirements. Condition: When sellers browse items listed by energy buyers and place orders against those requirements. Peers may list their surplus energy over half an hour for sale and place supply orders. Scope: Elecbay publishing and bidding period. Condition: During the publishing and bidding time period. Each supply order contains the energy-exchange time period, energy quantity, energy price, and seller and buyer details, including identities and energy-supply reliability ratings. Scope: Information contained in Elecbay supply orders. Peers may place, cancel or modify supply orders only before gate closure. Scope: Peer-initiated placement, cancellation and modification of Elecbay supply orders. Condition: Before gate closure, which is one hour before the energy exchange time period in this paper. DSOs alone have permission to modify or cancel supply orders in this condition. Scope: Modification or cancellation of Elecbay supply orders after gate closure. Condition: After gate closure, once a network constraint violation has been identified. Supply orders placed later, closer to gate closure, have a higher possibility of cancellation. Scope: Illustrative Elecbay order-modification or cancellation rule, applied to supply orders. Condition: If the example last on first off principle is used.","target_definition":"Peers submit surplus-energy sale listings during the publishing and bidding period, which ends at gate closure one hour before the corresponding energy exchange period. Scope: Elecbay peer publishing and bidding for a corresponding half-hourly energy exchange period. Peers submit required-energy purchase listings during the publishing and bidding period, which ends at gate closure one hour before the corresponding energy exchange period. Scope: Elecbay peer publishing and bidding for a corresponding half-hourly energy exchange period. Energy consumers and prosumers may trade energy with energy suppliers and with each other. Scope: Energy consumers and prosumers trading through Elecbay in LV distribution networks. Each peer generates or consumes the amount of energy promised in its accepted orders, with energy delivered through the distribution network. Scope: Elecbay energy exchange following the order acceptance/rejection process. Condition: The peer's order has been accepted. The peer is required to trade with suppliers at less beneficial selling or buying prices. Scope: Elecbay supplier trades addressing deviations from promised energy generation or consumption. Condition: A peer fails to generate or consume the promised amount of energy.","constraints":[{"constraint_id":"v141-c-R009-C001","kind":"procedural","role":"core","statement":"Peers submit surplus-energy sale listings during the publishing and bidding period, which ends at gate closure one hour before the corresponding energy exchange period. Scope: Elecbay peer publishing and bidding for a corresponding half-hourly energy exchange period.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev-21"]}],"evidence":[{"evidence_id":"v141-b-g01-ev-21","location":{"location_id":"src-c1934be9b4-p04-c1r4__v141-a-M02-bidding","page":4,"printed_page":null,"section":"3. Platform for Peer-to-Peer energy trading","anchor_text":"surplus energy over half an hour for sale, or the required energy over en half an hour for purchase)","equation_id":null,"figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"The publishing and bidding time period is the first time period of order process in Elecbay, during which peers are able to list items (the surplus energy over half an hour for sale, or the required energy over half an hour for purchase) and place orders. This time period starts several days, weeks or months before the half-hourly energy exchange time period, and ends by the gate closure, which is one hour before the energy exchange time period in this paper. Orders can be placed, cancelled or modified by peers only before the gate closure."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Elecbay energy exchange following the order acceptance/rejection process. | Elecbay peer publishing and bidding for a corresponding half-hourly energy exchange period. | Elecbay supplier trades addressing deviations from promised energy generation or consumption. | Energy consumers and prosumers trading through Elecbay in LV distribution networks.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-17","v141-b-g01-ev-18","v141-b-g01-ev-21","v141-b-g01-ev-28"]},"source_record":{"edge_id":"v141-c-R009-E002","source":"bidding.supply","target":"execution.energy_trade","type":"precedes","constraint_ids":["v141-c-R009-C001"],"evidence_ids":["v141-b-g01-ev-21"]},"paper_scope_note":"Buyer order placement and seller order placement are alternative processes; payment to the platform and the platform's distribution of bills are not the same data object; temporal order only preserves the source fact."}}],"assertion_ids":["12-p2p_microgrid_trading::v141-c-R009::E::v141-c-R009-E002"]});
